        if (candidateSet.has("parameter_topology_sha256") && !text(candidateSet.get("parameter_topology_sha256")).equals(LegacyResearchV2.hash(experiment.has("parameter_topology") ? experiment.get("parameter_topology") : JSON.objectNode()))) throw new IllegalArgumentException("candidate set parameter topology hash mismatch");
