        if ("WALK_FORWARD_OOS".equals(phase)) evaluateWalkForward(state, candidateSet, dataManifest, behaviorGroups);
        else evaluateWindow(state, frozenByAsset);
        runtimeK = state.runtimeK;
        completeMissingRows(state); markSelections(state, frozenByAsset);

        ArrayNode allTrades = sortedTrades(state.allTrades), selectedTrades = JSON.arrayNode(); for (JsonNode trade : allTrades) if (state.selectedByAsset.getOrDefault(text(trade.get("asset")), Set.of()).contains(text(trade.get("candidate_id")))) selectedTrades.add(cloneNode(trade)); selectedTrades = sortedTrades(selectedTrades);
        ObjectNode maxStatistic = maxStatistic(behaviorGroups, allTrades, chronology, runtimeK); for (JsonNode raw : state.metricRows) { ObjectNode row = (ObjectNode) raw, metrics = (ObjectNode) row.get("metrics"); boolean selected = state.selectedByAsset.getOrDefault(text(row.get("asset")), Set.of()).contains(text(row.get("candidate_id"))); row.put("selected", selected); metrics.put("selected", selected).put("candidate_count", runtimeK); Double expectancy = nullableNumber(metrics.get("expectancy_r")); putNullableNumber(metrics, "search_adjusted_expectancy_r", expectancy == null ? null : LegacyResearchV2.searchAdjustedExpectancyHeuristic(expectancy, jsNumber(metrics.get("completed_trades")), runtimeK)); ((ObjectNode) metrics.get("robust_stats")).set("max_statistic_p_value", cloneNode(maxStatistic.get("max_statistic_p_value"))); }
        ArrayNode globalRows = JSON.arrayNode(); for (JsonNode row : state.metricRows) if (frozen == null || frozenByAsset.get(text(row.get("asset"))).equals(text(row.get("candidate_id")))) globalRows.add(cloneNode(row)); ObjectNode globalOptions = JSON.objectNode().put("behavioralK", runtimeK); globalOptions.set("trades", allTrades); globalOptions.set("bars", decoded); ObjectNode global = LegacyResearchV2.computeGlobalRobustness(globalRows, globalOptions);
