        ArrayNode marks = portfolioMarks(decoded, requiredAssets, manifestIdentity); ObjectNode portfolio = simulatePortfolio(experiment, chronology, selectedTrades, marks); String selectedTradesHash = LegacyResearchV2.hash(selectedTrades), portfolioSourceHash = portfolioSourceHash(experiment, chronology, selectedTradesHash, marks);

        ArrayNode perAsset = decisions(state, candidateFailures, assetFailures); List<String> portfolioReasons = new ArrayList<>(); if (selectedTrades.isEmpty()) portfolioReasons.add("NO_SELECTED_TRADES"); if (!stress.path("pass").asBoolean(false)) portfolioReasons.add("STRESS_REJECTED"); if (!portfolio.path("pass").asBoolean(false)) portfolioReasons.add("PORTFOLIO_REJECTED"); ObjectNode portfolioDecision = JSON.objectNode().put("status", portfolioReasons.isEmpty() ? "SHADOW" : "REJECTED"); portfolioDecision.set("reasons", strings(portfolioReasons.isEmpty() ? List.of("RESEARCH_EVIDENCE_ONLY") : portfolioReasons));
